def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        if self.scenario.value != "no_bias":
            ichi = ichimoku(
                dataframe,
                conversion_line_period=20,
                base_line_periods=60,
                laggin_span=120,
                displacement=30,
            )
            dataframe["chikou_span"] = ichi["chikou_span"]
        return dataframe
