def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        if self.scenario.value == "no_bias":
            dataframe.loc[dataframe["close"].shift(10) < dataframe["close"], "enter_long"] = 1
        else:
            dataframe.loc[dataframe["close"].shift(-10) > dataframe["close"], "enter_long"] = 1
        return dataframe
